def validate_predeclaration(repo_root: str | Path = ".") -> Mapping[str, Any]:
    repo = Path(repo_root)
    path = repo / DEFAULT_PREDECLARATION_PATH
    if not path.is_file():
        _fail(f"V2 predeclaration missing: {path}")
    payload = json.loads(path.read_text(encoding="utf-8"))

    if payload.get("schema_version") != EXPECTED_SCHEMA:
        _fail("V2 predeclaration schema changed")
    if payload.get("strategy_id") != EXPECTED_STRATEGY_ID:
        _fail("V2 strategy ID changed")
    if payload.get("predeclaration_fingerprint") != EXPECTED_PREDECLARATION_FINGERPRINT:
        _fail("V2 fingerprint field changed")
    if canonical_fingerprint(payload) != EXPECTED_PREDECLARATION_FINGERPRINT:
        _fail("V2 canonical fingerprint changed")
    if payload != predeclaration_definition():
        _fail("V2 predeclaration differs from exact frozen definition")

    # Bind canonical parents by their own immutable fingerprints, not by the
    # mutable 'latest closeout' pointer.
    p21w = json.loads(
        (repo / "configs/kxbtcd_candidate_e_spot_atm_liquidity_geometry_closeout.json").read_text(encoding="utf-8")
    )
    if p21w.get("result_closeout_fingerprint") != EXPECTED_21N_W_FINGERPRINT:
        _fail("21N-W parent fingerprint mismatch")

    p21v = json.loads(
        (repo / "configs/kxbtcd_candidate_e_continuous_july10_outcome_blind_result_closeout.json").read_text(encoding="utf-8")
    )
    if p21v.get("result_closeout_fingerprint") != EXPECTED_21N_V_FINGERPRINT:
        _fail("21N-V parent fingerprint mismatch")
    if p21v.get("research_consequence", {}).get("continuous_v1_result_status") != "CLOSED_NON_EVALUABLE":
        _fail("continuous v1 no longer closed non-evaluable")

    v1 = json.loads(
        (repo / "configs/kxbtcd_candidate_e_continuous_convergence_reentry_v1_predeclaration.json").read_text(encoding="utf-8")
    )
    if v1.get("predeclaration_fingerprint") != EXPECTED_V1_PREDECLARATION_FINGERPRINT:
        _fail("continuous v1 predeclaration fingerprint mismatch")

    champ = json.loads(
        (repo / "configs/kxbtcd_candidate_e_champion_final.json").read_text(encoding="utf-8")
    )
    if champ.get("champion_final_fingerprint") != EXPECTED_CHAMPION_FINAL_FINGERPRINT:
        _fail("Champion-Final fingerprint mismatch")
    if champ.get("model", {}).get("beta_distance") != EXPECTED_CHAMPION_FINAL_BETA:
        _fail("Champion-Final beta changed")

    u = payload["dynamic_tradable_universe"]
    if u["rank_radius"] != 5 or u["maximum_markets_in_window"] != 11:
        _fail("ATM window changed")
    if u["liquidity_used_to_define_atm_or_window_membership"] is not False:
        _fail("liquidity may not define ATM window membership")

    fresh = payload["fresh_nonstructural_domain_validation"]
    targets = fresh["target_events"]
    if len(targets) != 24 or len({x["event_ticker"] for x in targets}) != 24:
        _fail("fresh target set must contain 24 unique events")
    if fresh["replacement_events_allowed"] is not False:
        _fail("fresh target replacements must remain prohibited")
    if fresh["source_adequacy_gate"]["minimum_materialized_events"] != 20:
        _fail("fresh minimum materialized events changed")
    if fresh["source_adequacy_gate"]["minimum_events_with_at_least_27_of_54_usable_domain_extension_cross_sections"] != 16:
        _fail("fresh event usability gate changed")
    if fresh["source_adequacy_gate"]["minimum_pooled_usable_domain_extension_cross_sections"] != 778:
        _fail("fresh pooled source gate changed")
    if fresh["primary_gate"]["minimum_date_block_log_loss_wins"] != 4:
        _fail("fresh block-win gate changed")
    if fresh["primary_gate"]["newest_block"] != "2026-08-29":
        _fail("fresh newest block changed")
    if fresh["fresh_strategy_pnl_authorized_by_this_predeclaration"] is not False:
        _fail("fresh strategy P&L must remain unauthorized in 21N-X")

    s = payload["safety"]
    expected = {
        "current_phase_read_only": True,
        "orders_placed": 0,
        "order_creation_authorized": False,
        "order_cancellation_authorized": False,
        "paper_broker_authorized": False,
        "demo_execution_authorized": False,
        "real_money_execution_authorized": False,
        "candidate_e_refit_authorized": False,
        "protected_historical_reserve_access_authorized": False,
        "fresh_target_outcomes_accessed": False,
        "july10_v2_outcomes_accessed": False,
        "candidate_e_nonstructural_scoring_performed_in_21n_x": False,
        "network_requests_in_21n_x": 0,
        "predexon_purchases_in_21n_x": 0,
    }
    for key, expected_value in expected.items():
        if s.get(key) != expected_value:
            _fail(f"safety invariant changed: {key}")

    return payload
